corrected_code:
import { json, ActionFunctionArgs } from '@remix-run/node';
import { db } from '~/db.server';
import { organizations } from '~/schema.server';
import { and, eq } from 'drizzle-orm';
import { requireUser } from '~/auth.server';

export async function action({ request, params }: ActionFunctionArgs) {
  const user = await requireUser(request);
  const { orgId } = params;

  const org = await db.query.organizations.findFirst({
    where: eq(organizations.id, orgId!)
  });
  if (!org || org.ownerId !== user.id) {
    return json({ error: 'Forbidden: you are not the owner of this organization' }, { status: 403 });
  }

  const deleted = await db.delete(organizations)
    .where(and(eq(organizations.id, orgId!), eq(organizations.ownerId, user.id)))
    .returning();

  return json({ success: true, deletedOrgId: orgId });
}
